  "title": "Kashaato",
  "localName": "Qumbe Cad — Kashaato",
  "emoji": "🥥",
  "country": "Somalia",
  "countryFlag": "🇸🇴",
  "region": "East Africa",
  "community": "Banaadir",
  "cuisine": "Somali",
  "category": "Desserts",
