  "title": "Doolshe Banaaddir",
  "localName": "Doolshe Banaaddir",
  "emoji": "🍮",
  "country": "Somalia",
  "countryFlag": "🇸🇴",
  "region": "East Africa",
  "community": "Banaadir",
  "cuisine": "Somali",
  "category": "Desserts",
