  "id": "SOM078",
  "title": "Ukun iyo Qudaar",
  "localName": "Ukun iyo Qudaar",
  "emoji": "🍳",
  "country": "Somalia",
  "countryFlag": "🇸🇴",
  "region": "East Africa",
  "community": "National",
  "cuisine": "Somali",
  "category": "Traditional Breakfasts",
  "course": "Breakfast / Brunch",
  "diff": "Easy",
  "prepTime": 15,
