  "localName": "Halwa ya Tanzania",
  "emoji": "🍮",
  "country": "Tanzania",
  "countryFlag": "🇹🇿",
  "community": "Zanzibar — the island's most prestigious confection",
  "cuisine": "Tanzanian / Swahili",
