  "title": "Umqa",
  "localName": "Umqa",
  "emoji": "🎃",
  "country": "South Africa",
  "countryFlag": "🇿🇦",
  "region": "Southern Africa",
  "community": "Xhosa (Eastern Cape)",
  "cuisine": "South African",
  "category": "Traditional Staples",
  "course": "Side Dish / Main",
