  "id": "ZAF032",
  "title": "Roosterkoek",
  "localName": "Roosterkoek",
  "emoji": "🔥",
  "country": "South Africa",
  "countryFlag": "🇿🇦",
  "region": "Southern Africa",
  "community": "National",
  "cuisine": "South African",
  "category": "Bread",
  "course": "Bread / Side",
  "diff": "Medium",
  "prepTime": 20,
  "restTime": 105,
  "cookTime": 20,
