  "id": "UGA016",
  "title": "Kikalayi",
  "localName": "Kikalayi",
  "emoji": "🥓",
  "country": "Uganda",
  "countryFlag": "🇺🇬",
  "region": "East Africa",
  "community": "Kampala Street Food",
