  "id": "UGA021",
  "title": "Bbuga",
  "localName": "Bbuga — Red Amaranth",
  "emoji": "🌿",
  "country": "Uganda",
  "countryFlag": "🇺🇬",
  "region": "East Africa",
  "community": "Buganda (Central)",
  "cuisine": "Ugandan",
  "category": "Vegetables & Legumes",
