  "id": "UGA024",
  "title": "Sombe",
  "localName": "Sombe — Isombe",
  "emoji": "🍃",
  "country": "Uganda",
  "countryFlag": "🇺🇬",
  "region": "East Africa",
  "community": "Bakonzo (Rwenzori)",
