  "id": "UGA029",
  "title": "Curry Termite Mushroom Soup",
  "localName": "Butiko",
  "emoji": "🍄",
  "country": "Uganda",
  "countryFlag": "🇺🇬",
  "region": "East Africa",
  "community": "Buganda (Central)",
  "cuisine": "Ugandan",
  "category": "Soups & Stews",
  "course": "Soup / Main Course",
