  "id": "UGA059",
  "title": "Gonja Plantain Donuts",
  "localName": "Gonja donuts",
  "emoji": "🍩",
  "country": "Uganda",
  "countryFlag": "🇺🇬",
  "region": "East Africa",
  "community": "Buganda (Central)",
  "cuisine": "Ugandan",
  "category": "Desserts & Sweets",
