  "id": "NGA071",
  "title": "Ekpang Nkukwo",
  "localName": "Ekpang nkukwo",
  "emoji": "🌯",
  "country": "Nigeria",
  "countryFlag": "🇳🇬",
  "region": "West Africa",
  "community": "Efik (Calabar)",
