  "id": "NGA085",
  "title": "Tuwo Masara",
  "localName": "Tuwo masara — tuo masara, corn tuwo",
  "emoji": "🌽",
  "country": "Nigeria",
  "countryFlag": "🇳🇬",
  "region": "West Africa",
  "community": "Hausa (North)",
  "cuisine": "Nigerian",
